      "pilot_obj_droplet_nearly": "Nọgide na-ekpokọta ntụpọ. Mgbe ị ruru {n}, gị na ntụpọ ndị gbara gị gburugburu ga-aghọ urukpu a na-ahụ anya.",
      "pilot_obj_groundwater": "Ị bụ mmiri okpuru ala, ị na-agafe oghere nkume: ọ bụghị mita n'otu sekọnd, kama mita ole na ole n'afọ. Chọta isi iyi maọbụ olulu mmiri iji laghachi.",
      "pilot_obj_ice": "Ị nọ mita {m} n'elu ọkwa oyi kpọnwụrụ. Ice na-eto ngwa ngwa karịa ntụpọ ndị gbara gị gburugburu: kpokọta, wee daa.",
      "pilot_obj_liquid": "Nọrọ na mmiri na-emighị emi ebe anwụ na-acha. Anwụ, ikuku kpọrọ nkụ na ifufe niile na-enye gị ike zuru iji mịpụ ma gbapụ.",
      "pilot_obj_liquid_nearly": "Ọ fọrọ nke nta ka ị bụrụ uzuoku: nọrọ na mmiri anwụ na-acha ruo mgbe ogwe ike ga-eju.",
      "pilot_obj_plant": "Otu mgbọrọgwụ mịkọrọ gị. Rịgoo site na xylem ruo otu akwụkwọ.",
      "pilot_obj_rain": "Ị na-ada dị ka mmiri ozuzo. Gaa n'ebe mmiri ghere oghe, ala na-amị mmiri, maọbụ osisi: nke ọ bụla ga-eziga gị n'ụzọ dị iche.",
      "pilot_obj_runoff": "Ị enweghị ike ịbanye n'ala, ya mere ị na-asọ n'elu ala gaa n'iyi. Soro mgbadata ala gbadaa.",
      "pilot_obj_snow": "Ị na-ada dị ka snow. Ọ bụrụ na ị gbadaa n'okpuru mita {m} ị ga-agbaze n'etiti ụzọ ma ghọọ mmiri ozuzo.",
      "pilot_obj_soil": "Ị banyela n'ala. Gbadaa gaa n'ọkwa mmiri okpuru ala, maọbụ hapụ ka otu mgbọrọgwụ mịkọrọ gị.",
      "pilot_obj_transpiring": "Ị na-apụta site n'oghere akwụkwọ. N'ime nkeji ole na ole ị ga-abụ uzuoku ọzọ, okirikiri ga-amalitekwa ọzọ.",
      "pilot_obj_vapor_climb": "Rịgoo. Na mita {m} ikuku ajụọla ruo n'ebe igirigi gị, mkpokọta nwekwara ike ịmalite: ọ bụghị ọbụna otu mita n'okpuru ya.",
      "pilot_obj_vapor_nucleus": "Ị nọ n'elu ala urukpu ma jupụtakwa na mmiri, mana uzuoku anaghị agbakọta n'elu ihe efu. Fee gaa n'isi mkpokọta: ntụ na obere nnu oke osimiri na-ese n'ikuku.",
      "pilot_one_flight_cannot_reach_every_stage_wh": "Otu ịnya efe apụghị iru nkeji niile: ebe ị na-arịda na-ekpebi ụzọ gị. Feekwa ọzọ ma rịdaa n'ebe ọzọ.",
